      "heading_8": "Support",
      "heading_9": "Newsletter",
      "paragraph_10": "From expert grooming to compassionate veterinary care, we provide everything your furry friend needs to\n              thrive in a soft, stress-free environment.",
      "paragraph_11": "We offer a full range of care services designed to keep your pets healthy, clean, and wagging their tails.",
      "paragraph_12": "Full spa treatments, breed-specific cuts, and gentle nail trimming for all sizes.",
      "paragraph_13": "Routine checkups, vaccinations, and wellness exams\n                by our compassionate vets.",
      "paragraph_14": "A safe, fun environment for your pets to socialize\n                and play while you're away.",
      "paragraph_15": "Join the Pawsitive family today and experience the difference of compassionate, professional pet care.",
      "paragraph_16": "Providing gentle, loving care for your furry family members since 2015. Your pet's happiness is our\n              priority.",
      "paragraph_17": "Get pet care tips and special offers!",
