      "heading_6": "Support",
      "heading_7": "Newsletter",
      "paragraph_8": "Comprehensive care solutions tailored to your pet's unique personality and health requirements.",
      "paragraph_9": "Our spa treatments include organic shampoos, breed-specific styling, and a stress-free environment that keeps pets calm and happy.",
      "paragraph_10": "Preventative care is the foundation of a long, healthy life. Our vets provide thorough exams and personalized health plans.",
      "paragraph_11": "Socialization and play are vital for a balanced pet. Our daycare offers supervised group play and cozy nap areas.",
      "paragraph_12": "Providing gentle, loving care for your furry family members since 2015. Your pet's happiness is our priority.",
